def _pop(stack, count):
    if len(stack) < count:
        raise StackUnderflowError("Insufficient number of items in stack")
    return [stack.pop() for _ in range(count)]


def _trunc_div(a, b):
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    q = a // b
    if a % b != 0 and (a < 0) != (b < 0):
        q += 1
    return q


def _execute_builtin(name, stack):
    if name == "+":
        b, a = _pop(stack, 2)
        stack.append(a + b)
    elif name == "-":
        b, a = _pop(stack, 2)
        stack.append(a - b)
    elif name == "*":
        b, a = _pop(stack, 2)
        stack.append(a * b)
    elif name == "/":
        b, a = _pop(stack, 2)
        stack.append(_trunc_div(a, b))
    elif name == "dup":
        if not stack:
            raise StackUnderflowError("Insufficient number of items in stack")
        stack.append(stack[-1])
    elif name == "drop":
        _pop(stack, 1)
    elif name == "swap":
        b, a = _pop(stack, 2)
        stack.extend((a, b))
    elif name == "over":
        if len(stack) < 2:
            raise StackUnderflowError("Insufficient number of items in stack")
        stack.append(stack[-2])
    else:
        raise ValueError("undefined operation")


def evaluate(input_data):
    stack = []
    words = {}

    def execute(tokens):
        for token in tokens:
            if _is_number(token):
                stack.append(int(token))
            else:
                name = token.lower()
                if name in words:
                    execute(words[name])
                else:
                    _execute_builtin(name, stack)

    for line in input_data:
        tokens = line.split()
        if not tokens:
            continue
        if tokens[0] == ":":
            name = tokens[1].lower()
            if _is_number(tokens[1]):
                raise ValueError("illegal operation")
            body = tokens[2:-1]
            expanded = []
            for token in body:
                if not _is_number(token) and token.lower() in words:
                    expanded.extend(words[token.lower()])
                else:
                    expanded.append(token)
            words[name] = expanded
        else:
            execute(tokens)

    return stack
